head.script:
    scwin.onpageload = function() {
        trigger1.setLabel("조회");
        trigger2.setLabel("setColumnFilter: \"ID===F_6\"");
        trigger3.setLabel("setColumnFilter: \"col1===0\"");
        trigger4.setLabel("\"ID===F_6\" , clearFilter:\"keepSort\"");
        trigger5.setLabel("\"col1===0\" , clearFilter:\"keepSort\"");
        trigger6.setLabel("\"ID===F_6\" , clearFilter:\"all\"");
        trigger7.setLabel("\"col1===0\" , clearFilter:\"all\"");
    }

    scwin.trigger1_onclick = function(e) {
        var row = 100;
        var data = [];
        for (var i = 0; i < row; i++) {
            data.push("F_" + (i + 1) + "_");
            data.push(String(i % 5));
        }
        dataList1.setData(data);
    }

    scwin.trigger2_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "ID", 
            "key" : "F_6", 
            "condition" : "and", 
            "exactMatch" : false
        }
        dataList1.setColumnFilter(filterOption);
    };

    scwin.trigger3_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "col1", 
            "key" : "0", 
            "condition" : "and", 
            "exactMatch" : false
        }
        dataList1.setColumnFilter(filterOption);
    };

    scwin.trigger4_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "ID", 
            "key" : "F_6", 
            "condition" : "and", 
            "exactMatch" : false,
            "clearFilter" : "keepSort"
        }
        dataList1.setColumnFilter(filterOption);
    };

    scwin.trigger5_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "col1", 
            "key" : "0", 
            "condition" : "and", 
            "exactMatch" : false,
            "clearFilter" : "keepSort"
        }
        dataList1.setColumnFilter(filterOption);
    };

    scwin.trigger6_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "ID", 
            "key" : "F_6", 
            "condition" : "and", 
            "exactMatch" : false,
            "clearFilter" : "all"
        }
        dataList1.setColumnFilter(filterOption);
    };

    scwin.trigger7_onclick = function(e) {
        var filterOption = {
            "type" : "row", 
            "colIndex" : "col1", 
            "key" : "0", 
            "condition" : "and", 
            "exactMatch" : false,
            "clearFilter" : "all"
        }
        dataList1.setColumnFilter(filterOption);
    };




	scwin.findLastRowIndex = function() {	
		const tbody = WebSquare.wUnit.getDomById('gridView1_body_tbody');
		const rows = tbody.querySelectorAll("tr");


		let lastRowIndex = -1; 
		for (let index = 0; index < rows.length; index++) {
			const row = rows[index];
			if (row.classList.contains("w2grid_lastRow")) {
				lastRowIndex = index; 
				return lastRowIndex;
			}else{
				lastRowIndex = index; 
			}
		}
debugger;
		return lastRowIndex;

	}

	scwin.Dbclick = function(id) {
		var el = WebSquare.wUnit.getDomById(id);
		scwin.fireDbClick(el);
	}
	scwin.fireDbClick = function(node) {
		if (document.createEventObject) {
			node.fireEvent('ondblclick');
		} else if (document.createEvent) {
			var evt = document.createEvent('MouseEvents');
			evt.initEvent('dblclick', true, false);
			node.dispatchEvent(evt);
		} else if (typeof node.ondblclick == 'function') {
			node.ondblclick();
		}
	}	
	scwin.checkVal1 = function() {
		return scwin.findLastRowIndex() > 12;
	}
	scwin.checkVal3 = function() {
		const check1 = window.rowIndex_oncontextopen == 1;
		const check2 = window.row_rightbtn == 1;
		return check1 && check2;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.Dbclick('gridView1_column7')");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger7').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");				

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
